const errorDe = (j) => (j && j.exception) ? (j.errorcode + ': ' + j.message) : null;
const cursoResp = $('Buscar curso').first().json;
const tareasResp = $('Tareas del curso').first().json;
const entregasResp = $('Entregas').first().json;
const errores = [errorDe(cursoResp), errorDe(tareasResp), errorDe(entregasResp)].filter(Boolean);
for (const it of $('Alumnos inscritos').all()) { const e = errorDe(it.json); if (e) errores.push(e); }

const c = (cursoResp.courses || [])[0];
if (!c) return [{ json: { ok: false, error: 'No encontré el curso en Moodle', errores } }];

const limpiar = (html) => String(html || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();
const fecha = (ts) => ts ? new Date(ts * 1000).toLocaleString('es-PE', { timeZone: 'America/Lima', weekday: 'long', day: 'numeric', month: 'long', hour: '2-digit', minute: '2-digit' }) : null;

const alumnos = $('Alumnos inscritos').all().map(i => i.json)
  .filter(u => u && u.id && (!u.roles || u.roles.length === 0 || u.roles.some(r => r.shortname === 'student')))
  .map(u => ({
    moodleId: u.id,
    nombre: u.fullname,
    email: u.email || null,
    telefono: ((u.customfields || []).find(f => f.shortname === 'telefono') || {}).value || null
  }));

const subsPorTarea = {};
for (const a of (entregasResp.assignments || [])) subsPorTarea[a.assignmentid] = a.submissions || [];

const tareas = (((tareasResp.courses || [])[0] || {}).assignments || []).map(t => {
  const entregaronIds = new Set((subsPorTarea[t.id] || []).filter(s => s.status === 'submitted').map(s => s.userid));
  return {
    moodleId: t.id,
    nombre: t.name,
    fechaEntrega: fecha(t.duedate),
    fechaEntregaUnix: t.duedate || null,
    enunciado: limpiar(t.intro),
    entregaron: alumnos.filter(a => entregaronIds.has(a.moodleId)).map(a => a.nombre),
    pendientes: alumnos.filter(a => !entregaronIds.has(a.moodleId)).map(a => ({ nombre: a.nombre, telefono: a.telefono }))
  };
});

return [{ json: {
  ok: errores.length === 0,
  errores,
  curso: { moodleId: c.id, nombre: c.fullname, shortname: c.shortname },
  totalAlumnos: alumnos.length,
  alumnos,
  tareas
} }];
